exec(open('/app/output/skeleton.py').read().split("sk=np.zeros_like(T)")[0])
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import dijkstra
from scipy.spatial import cKDTree
# thin each sufficiently big comp
sk=np.zeros_like(T)
for i in range(1,n+1):
 if (lab==i).sum()>500: sk |= thin(lab==i)
yx=np.argwhere(sk); index={tuple(p):i for i,p in enumerate(yx)}
rows=[];cols=[];data=[]
for i,(y,x) in enumerate(yx):
 for dy in (-1,0,1):
  for dx in (-1,0,1):
   if dx==dy==0:continue
   j=index.get((y+dy,x+dx))
   if j is not None:
    rows.append(i);cols.append(j);data.append(1.41421356 if dx and dy else 1.)
g=coo_matrix((data,(rows,cols)),shape=(len(yx),len(yx))).tocsr(); tree=cKDTree(yx[:,::-1])
def nearest(p): return int(tree.query(p)[1])
def route(a,b):
 ia,ib=nearest(a),nearest(b)
 dist,pred=dijkstra(g,directed=True,indices=ia,return_predecessors=True)
 path=[ib]
 while path[-1]!=ia:
  prev=int(pred[path[-1]])
  if prev<0:raise ValueError((a,b))
  path.append(prev)
 path=path[::-1]
 return yx[path][:,::-1].astype(float)
def sample(path,spacing=8):
 seg=np.linalg.norm(np.diff(path,axis=0),axis=1);cum=np.r_[0,np.cumsum(seg)]
 out=[]
 for q in np.r_[np.arange(0,cum[-1],spacing),cum[-1]]:
  j=min(np.searchsorted(cum,q,side='right')-1,len(seg)-1)
  t=(q-cum[j])/max(seg[j],1e-9)
  out.append(path[j]+t*(path[j+1]-path[j]))
 return np.round(out,1).tolist()
